import Model from 'flarum/common/Model';
export default class GoogleNewsMeta extends Model {
  discussion() {
    return Model.hasOne('discussion').call(this);
  }
  isNews() {
    return Model.attribute('isNews').call(this);
  }
  enableStructuredData() {
    return Model.attribute('enableStructuredData').call(this);
  }
  includeInSitemap() {
    return Model.attribute('includeInSitemap').call(this);
  }
  includeInFeed() {
    return Model.attribute('includeInFeed').call(this);
  }
  headline() {
    return Model.attribute('headline').call(this);
  }
  description() {
    return Model.attribute('description').call(this);
  }
  category() {
    return Model.attribute('category').call(this);
  }
  language() {
    return Model.attribute('language').call(this);
  }
  coverImage() {
    return Model.attribute('coverImage').call(this);
  }
  authorName() {
    return Model.attribute('authorName').call(this);
  }
  authorUrl() {
    return Model.attribute('authorUrl').call(this);
  }
}
flarum.reg.add('cengizkemec-google-news', 'common/GoogleNewsMeta', GoogleNewsMeta);